# Đợt 5 sau kiểm thử (v117): 1 / 2 trang, Trang / Cuộn, nút 🔍 mở Task, đèn pin, bảng trắng chế độ Text, hộp Note.
# Cách dùng: python3 tests/sau_kiem_thu/test_dot5.py <app.html> [thư mục ảnh]
import sys, os
from playwright.sync_api import sync_playwright
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from chung import *

PAGES = "() => [...document.querySelectorAll('#wsShow .vpages > .vpage')].map(e => +e.dataset.pg)"
with sync_playwright() as p:
    pg, b = mo(p, sys.argv[1])
    n = pg.evaluate("() => +document.querySelector('#showCur').textContent.split('/')[1]")
    chk('E1 mặc định 1 trang', pg.evaluate(PAGES) == [0], pg.evaluate(PAGES))
    tb(pg, '#showTwo')
    chk('E1 bấm 2 trang: hai trang cạnh nhau, cùng hàng', pg.evaluate(PAGES) == [0, 1] and pg.evaluate("() => { const [a, b] = [...document.querySelectorAll('#wsShow .vpage')].map(e => e.getBoundingClientRect()); return Math.abs(a.top - b.top) < 1 && b.left > a.right; }"))
    box = pg.evaluate("() => { const r = document.querySelector('#wsShow .vbox').getBoundingClientRect(); return [r.width, r.height]; }")
    chk('E1 hai trang vừa màn hình', box[0] <= 1920 and box[1] <= 1080, box)
    chk('E1 thanh ghi "Trang 1–2/n"', pg.inner_text('#showCur') == f'Trang 1–2/{n}', pg.inner_text('#showCur'))
    pg.screenshot(path=f'{SHOT}/d5_hai_trang.png')
    key(pg, 'ArrowRight')
    chk('E1 lật: sang trang 3–4', pg.evaluate(PAGES) == [2, 3], pg.evaluate(PAGES))
    key(pg, 'a'); pg.wait_for_timeout(80)
    v = pg.evaluate("() => [...document.querySelectorAll('#wsShow .vpage')].map(p => p.querySelectorAll('.vans, .vok, svg.vline').length)")
    chk('E1 A hiện đáp án cả hai trang đang xem', all(x > 0 for x in v), v)
    key(pg, 'a')
    # nét vẽ ở trang phải vẫn đúng chỗ khi về 1 trang
    pg.keyboard.down('Shift'); r = pg.evaluate("() => { const r = document.querySelectorAll('#wsShow .vpage')[1].getBoundingClientRect(); return [r.left + r.width * .3, r.top + r.height * .02]; }")
    pg.mouse.move(r[0], r[1]); pg.mouse.down(); pg.mouse.move(r[0] + 120, r[1], steps=4); pg.mouse.up(); pg.keyboard.up('Shift'); pg.wait_for_timeout(80)
    k = pg.evaluate("() => Object.keys(JSON.parse(localStorage.getItem(Object.keys(localStorage).find(x => x.startsWith('wsShow.ink:')))).ink)")
    chk('E1 vẽ ở lề trang phải: nét gắn trang 4', 'page#3' in k, k)
    tb(pg, '#showTwo'); key(pg, 'ArrowRight')
    chk('E1 về 1 trang: lật từng trang', pg.evaluate(PAGES) == [3], pg.evaluate(PAGES))
    chk('E1 nét của trang 4 vẫn hiện', pg.evaluate("() => document.querySelectorAll('#wsShow .vink path').length") >= 1)
    pg.click('#inkClear'); pg.click('#inkClearAll'); pg.wait_for_timeout(60)
    # E3 Cuộn
    key(pg, 'Home'); tb(pg, '#showScroll')
    chk('E3 Cuộn: mọi trang xếp dọc liền', pg.evaluate(PAGES) == list(range(n)), pg.evaluate(PAGES))
    tops = pg.evaluate("() => [...document.querySelectorAll('#wsShow .vpage')].map(e => e.getBoundingClientRect().top)")
    chk('E3 trang sau nằm dưới trang trước', all(tops[i] < tops[i + 1] for i in range(len(tops) - 1)))
    key(pg, 'ArrowRight'); pg.wait_for_timeout(700)
    t2 = pg.evaluate("() => document.querySelectorAll('#wsShow .vpage')[1].getBoundingClientRect().top")
    chk('E3 lật = cuộn tới đầu trang kế', abs(t2 - 12) < 16 and pg.inner_text('#showCur').startswith('Trang 2/'), (t2, pg.inner_text('#showCur')))
    pg.mouse.move(960, 540); pg.mouse.wheel(0, 2400); pg.wait_for_timeout(500)
    chk('E3 cuộn tự do: thanh ghi trang đang xem', pg.inner_text('#showCur') != 'Trang 2/' + str(n), pg.inner_text('#showCur'))
    pg.screenshot(path=f'{SHOT}/d5_cuon.png')
    tb(pg, '#showTwo'); chk('E3 + E1: Cuộn hai trang một hàng', len(pg.evaluate(PAGES)) == n and pg.evaluate("() => { const [a, b] = [...document.querySelectorAll('#wsShow .vpage')].map(e => e.getBoundingClientRect().top); return Math.abs(a - b) < 1; }"))
    tb(pg, '#showTwo'); tb(pg, '#showScroll'); chk('E3 tắt Cuộn: về một trang', len(pg.evaluate(PAGES)) == 1)
    # E5 nút 🔍
    key(pg, 'Home')
    z = pg.query_selector("#wsShow section.task[data-frag='0'] .vzt")
    chk('E5 mỗi Task có nút 🔍 bên trái nút ✓', z is not None and pg.evaluate("() => { const s = document.querySelector('#wsShow section.task[data-frag=\"0\"]'), z = s.querySelector('.vzt').getBoundingClientRect(), t = s.querySelector('.vtk'); return !t || z.right <= t.getBoundingClientRect().left + 1; }"))
    tid = pg.evaluate("() => document.querySelectorAll('#wsShow section.task[data-frag=\"0\"]')[1].dataset.task")
    pg.click(f"#wsShow section.task[data-task='{tid}'][data-frag='0'] .vzt"); pg.wait_for_timeout(150)
    chk('E5 bấm 🔍: mở Từng Task đúng Task đó', pg.evaluate("() => document.querySelector('#wsShow .vstage').dataset.mode") == 'task' and pg.evaluate("() => document.querySelector('#wsShow section.task').dataset.task") == tid)
    chk('E5 ở Từng Task không còn nút 🔍', pg.query_selector('#wsShow .vzt') is None)
    key(pg, 't')
    # E6 đèn pin
    key(pg, 'l'); pg.mouse.move(800, 400); pg.mouse.move(820, 410); pg.wait_for_timeout(60)
    bg = pg.evaluate("() => document.querySelector('#torch') && document.querySelector('#torch').style.background")
    chk('E6 phím L: bật đèn pin, vòng sáng theo chuột', bg and '820px 410px' in bg and '0.92' in bg, bg)
    pg.screenshot(path=f'{SHOT}/d5_den_pin.png')
    pg.mouse.wheel(0, -100); pg.wait_for_timeout(60)
    bg2 = pg.evaluate("() => document.querySelector('#torch').style.background")
    chk('E6 lăn chuột: đổi cỡ vòng sáng (không phóng trang)', bg2 != bg and pg.inner_text('#showZoom') == 'Vừa', (bg2[:60], pg.inner_text('#showZoom')))
    pg.mouse.click(820, 410); chk('E6 bấm xuyên đèn pin vẫn được', pg.query_selector('#torch') is not None)
    key(pg, 'Escape'); chk('E6 Esc tắt đèn pin, trình chiếu vẫn mở', pg.query_selector('#torch') is None and pg.query_selector('#wsShow') is not None)
    # E11 hộp Note
    pg.evaluate("() => localStorage.removeItem(Object.keys(localStorage).find(x => x.startsWith('wsShow.note:')) || 'x')")
    t = pg.evaluate("() => { const h = document.querySelector('#wsShow section.task .g0, #wsShow section.task .ttl, #wsShow section.task h2, #wsShow section.task'), r = h.getBoundingClientRect(); return [r.left + r.width * .6, r.top + 6]; }")
    pg.mouse.dblclick(t[0], t[1]); pg.wait_for_timeout(120)
    chk('E11 bấm đúp: mở hộp ghi chú, con trỏ ở trong', pg.evaluate("() => document.activeElement && document.activeElement.classList.contains('vntt')"))
    pg.keyboard.type('Hỏi thêm: why? p e t'); pg.wait_for_timeout(60)
    chk('E11 gõ chữ không chạy phím tắt (p, e, t)', pg.evaluate("() => document.querySelector('#wsShow .vstage').dataset.tool") == 'pointer' and pg.evaluate("() => document.querySelector('#wsShow .vstage').dataset.mode") == 'page')
    h1 = pg.evaluate("() => document.querySelector('#wsShow .vnt').getBoundingClientRect().height")
    pg.keyboard.press('Enter'); pg.keyboard.type('dòng hai'); pg.wait_for_timeout(60)
    chk('E11 hộp tự giãn theo chữ', pg.evaluate("() => document.querySelector('#wsShow .vnt').getBoundingClientRect().height") > h1 + 5)
    pg.screenshot(path=f'{SHOT}/d5_note.png')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(60)
    chk('E11 Esc trong hộp: chỉ thôi gõ, trình chiếu còn mở', pg.query_selector('#wsShow') is not None and pg.query_selector('#wsShow .vnt') is not None)
    saved = pg.evaluate("() => { const k = Object.keys(localStorage).find(x => x.startsWith('wsShow.note:')); return k ? JSON.stringify(JSON.parse(localStorage.getItem(k)).notes) : ''; }")
    chk('E11 lưu trên máy (gắn với Task)', 'dòng hai' in saved and '#0' in saved, saved[:200])
    key(pg, 't'); task(pg, 1); pg.wait_for_timeout(200); chk('E11 sang Từng Task: ghi chú vẫn ở Task đó', pg.query_selector('#wsShow .vnt') is not None, pg.evaluate("() => [document.querySelector('#wsShow .vstage').dataset.mode, document.querySelector('#wsShow .vnotes') && document.querySelector('#wsShow .vnotes').innerHTML.slice(0, 200), localStorage.getItem(Object.keys(localStorage).find(x => x.startsWith('wsShow.note:')))]")); key(pg, 't'); pg.wait_for_timeout(200)
    pg.click('#wsShow .vnt [aria-label="Thu gọn"]'); pg.wait_for_timeout(60)
    chk('E11 thu gọn thành nhãn 📝', pg.query_selector('#wsShow .vntc') is not None and pg.query_selector('#wsShow .vntt') is None)
    pg.click('#wsShow .vntc'); pg.wait_for_timeout(60); chk('E11 bấm nhãn: mở lại', pg.query_selector('#wsShow .vntt') is not None)
    chk('E11 không có nhận giọng nói thì ẩn nút mic (Chromium không đầu)', (pg.query_selector('#wsShow .vnt [aria-label="Nói"]') is not None) == pg.evaluate("() => !!(window.SpeechRecognition || window.webkitSpeechRecognition)"))
    pg.click('#wsShow .vnt [aria-label="Xóa ghi chú"]'); pg.wait_for_timeout(60)
    chk('E11 xóa ghi chú', pg.query_selector('#wsShow .vnt') is None and not pg.evaluate("() => Object.keys(localStorage).some(x => x.startsWith('wsShow.note:'))"))
    ids = pg.evaluate("() => [...document.querySelectorAll('#wsShow [data-ans]')].slice(0, 1).map(e => e.dataset.ans)")
    pg.dblclick(S(ids[0])); pg.wait_for_timeout(80)
    chk('E11 bấm đúp vào chỗ trả lời: không mở ghi chú', pg.query_selector('#wsShow .vnt') is None)
    pg.evaluate("() => document.activeElement && document.activeElement.blur()")
    # E10 bảng trắng chế độ Text
    key(pg, 'b'); pg.click('#boardText')
    sr = pg.evaluate("() => { const r = document.querySelector('#boardSurf').getBoundingClientRect(); return [r.left, r.top]; }")
    pg.mouse.click(sr[0] + 300, sr[1] + 130); pg.wait_for_timeout(80)
    pg.keyboard.type('Present simple'); pg.wait_for_timeout(60)
    y = pg.evaluate("() => parseFloat(document.querySelector('#boardSurf .vbtx').style.top)")
    chk('E10 kẻ dòng: bấm đâu gõ đó, chữ dóng vào dòng kẻ gần nhất', y == 1 * 57 + 10 and pg.evaluate("() => document.querySelector('#boardSurf .vbtx').value") == 'Present simple', y)
    chk('E10 gõ chữ trên bảng không đóng bảng (phím b)', pg.query_selector('#wsShow .vboard') is not None)
    pg.select_option('#wsShow .vboard .vsel', 'grid'); pg.mouse.click(sr[0] + 500, sr[1] + 300); pg.wait_for_timeout(80); pg.keyboard.type('x'); pg.wait_for_timeout(60)
    g = pg.evaluate("() => { const e = [...document.querySelectorAll('#boardSurf .vbtx')].pop(); return [parseFloat(e.style.left), parseFloat(e.style.top)]; }")
    chk('E10 kẻ ô: chữ vào góc ô', g == [13 * 36 + 2, 8 * 36], g)
    pg.screenshot(path=f'{SHOT}/d5_bang_chu.png')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(40); pg.keyboard.press('Control+z'); pg.wait_for_timeout(60)
    chk('E10 Ctrl+Z bỏ dòng chữ vừa thêm', pg.evaluate("() => document.querySelectorAll('#boardSurf .vbtx').length") == 1, pg.evaluate("() => document.querySelectorAll('#boardSurf .vbtx').length"))
    pg.click('#boardClear'); chk('E10 Xóa bảng xóa cả chữ', pg.evaluate("() => document.querySelectorAll('#boardSurf .vbtx').length") == 0)
    pg.click('#boardClose')
    xong(b)
